const Collection=(()=>{
 const BASE='https://aiguillage-participations.milkycomet4097.chatgpt.site';
 const VERSION='2026-10-31-v1',GAME='aiguillage-40-2026-10',KEY='aiguillage-retraits-v1';
 let queue=Promise.resolve();const revoked=new Set();
 const receipts=()=>{try{return JSON.parse(sessionStorage.getItem(KEY)||'[]')}catch{return []}};
 const keep=r=>{const all=receipts().filter(x=>x.id!==r.id);all.push({id:r.id,token:r.token,withdrawn:!!r.withdrawn});sessionStorage.setItem(KEY,JSON.stringify(all));};
 function random(n,hex=false){const b=crypto.getRandomValues(new Uint8Array(n));return hex?Array.from(b,v=>v.toString(16).padStart(2,'0')).join(''):btoa(String.fromCharCode(...b)).replaceAll('+','-').replaceAll('/','_').replaceAll('=','');}
 function information(){return `<p>Vous pouvez transmettre vos réponses à <b>Christophe Gauld</b> pour analyser les choix dans ce jeu et leurs liens avec les profils professionnels</p><p>Les informations transmises comprennent vos choix initiaux et finaux et, si vous les avez renseignés, votre âge, votre genre, votre profession, vos années de pratique et <b>votre ville précise</b></p><p>Aucun nom ni e-mail n’est demandé, mais le croisement de ces informations peut permettre de reconnaître une personne — cette collecte est confidentielle, elle ne garantit pas un anonymat strict</p><p>Les résultats sont consultables uniquement par Christophe Gauld, dans un espace privé distinct de GitHub<br>Durée de conservation : 12 mois, avec suppression quotidienne des participations arrivées à échéance</p><p>Vous pouvez retirer vos réponses et votre profil à tout moment avec un code de retrait, sans fournir votre identité</p><p class="fineprint">Refuser ne change pas le jeu<br>L’application n’enregistre ni adresse IP ni navigateur avec les réponses — les hébergeurs peuvent conserver des journaux techniques de connexion<br>Ne renseignez ni nom de patient, ni nom personnel ou d’employeur dans les champs libres</p>`;}
 function offer(){if(state.remote?.consent!==undefined)return;state.remote={consent:false,saved:0};save();openDialog('Participer à la collecte ?',information()+`<label class="check"><input id="collection-agree" type="checkbox"> J’ai 18 ans ou plus et j’accepte volontairement la transmission des informations décrites ci-dessus</label><div class="form-actions"><button class="plain-btn" data-collection="decline">Jouer sans transmettre</button><button class="ticket" data-collection="accept" disabled>Accepter et jouer →</button></div>`);}
 function accept(){if(!document.querySelector('#collection-agree')?.checked)return;if(state.profile?.age!==null&&state.profile?.age!==undefined&&state.profile.age<18){toast('La collecte est réservée aux adultes — vous pouvez jouer sans transmettre');return;}const r={consent:true,id:Math.floor(Date.now()/86400000).toString(16).padStart(8,'0')+random(12,true),token:random(32),saved:0,status:'ready',withdrawn:false,profile:state.profile?JSON.parse(JSON.stringify(state.profile)):null};state.remote=r;keep(r);save();closeDialog();toast('Participation acceptée — seules les situations terminées seront transmises');}
 async function post(path,payload,authorization){const abort=new AbortController(),timeout=setTimeout(()=>abort.abort(),12000);try{const response=await fetch(BASE+path,{method:'POST',headers:{'Content-Type':'application/json',...(authorization?{Authorization:'Bearer '+authorization}:{})},body:JSON.stringify(payload),credentials:'omit',referrerPolicy:'no-referrer',cache:'no-store',signal:abort.signal});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Transmission impossible');return data;}finally{clearTimeout(timeout);}}
 function refresh(r){if(state.remote?.id===r.id){save();const status=document.querySelector('#collection-status');if(status)status.outerHTML=statusMarkup();}}
 function send(){const r=state.remote;if(!r?.consent||r.withdrawn||!state.records.length)return;const responses=state.records.map(x=>({id:x.id,first:x.first,final:x.final,revised:x.revised,third:x.third}));const payload={id:r.id,withdrawalToken:r.token,consent:true,consentVersion:VERSION,gameVersion:GAME,profile:r.profile,responses};r.status='sending';refresh(r);
 queue=queue.then(async()=>{if(revoked.has(r.id))return;try{const a=await post('/api/authorize',{id:r.id});if(revoked.has(r.id))return;const saved=await post('/api/participations',payload,a.token);r.saved=Math.max(r.saved||0,saved.saved);r.status='saved';}catch{r.status='error';}refresh(r);});return queue;}
 function statusMarkup(){const r=state.remote;let text='Aucune réponse transmise — participation à la collecte désactivée';if(r?.consent&&!r.withdrawn)text=r.status==='sending'?'Transmission des réponses en cours':r.status==='error'?'Transmission non confirmée — vos réponses restent disponibles dans cet onglet':r.saved?`${r.saved} réponse${r.saved>1?'s':''} reçue${r.saved>1?'s':''} dans la collecte privée`:'Accord enregistré — les situations terminées seront transmises';return `<section id="collection-status" class="collection-status" aria-live="polite"><p>${text}</p><button class="plain-btn" data-collection="manage">Ma participation</button>${r?.status==='error'&&r?.consent?'<button class="plain-btn" data-collection="retry">Réessayer la transmission</button>':''}</section>`;}
 function manage(){const r=state.remote;const codes=receipts().filter(x=>!x.withdrawn);openDialog('Ma participation',`<p>${r?.consent&&!r.withdrawn?'Vous avez accepté la collecte pour ce parcours':'Aucune transmission n’est active pour ce parcours'}</p>${r?.consent?`<p>${r.saved||0} réponses confirmées reçues</p>`:''}<p>Les codes ci-dessous permettent de retirer une participation, sans révéler votre identité<br>Conservez-les avant de fermer cet onglet</p>${codes.length?codes.map((c,i)=>`<div class="withdrawal-code"><b>Participation ${i+1}</b><code>${escapeHTML(c.id+'.'+c.token)}</code><button class="plain-btn" data-collection="download-code" data-id="${c.id}">Enregistrer le code</button><button class="plain-btn" data-collection="withdraw" data-id="${c.id}">Retirer cette participation</button></div>`).join(''):'<p>Aucune participation transmise depuis cet onglet</p>'}<p><a href="${BASE}/retrait" target="_blank" rel="noopener noreferrer">Retirer une participation avec un code conservé ↗</a></p><details><summary>Conditions de la collecte</summary>${information()}</details>`);}
 function downloadCode(id){const r=receipts().find(x=>x.id===id);if(!r)return;const blob=new Blob([`L’Aiguillage — code de retrait\n\n${r.id}.${r.token}\n\nRetrait : ${BASE}/retrait\n\nCe code permet uniquement de supprimer votre participation\nConservez-le sans le partager\n`],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='aiguillage-code-retrait.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 function withdraw(id){const r=receipts().find(x=>x.id===id);if(!r)return;revoked.add(id);if(state.remote?.id===id){state.remote.consent=false;state.remote.withdrawn=true;save();}openDialog('Retrait en cours',`<p>Les nouveaux envois sont arrêtés — la suppression de la participation est en cours</p>`);queue=queue.then(async()=>{try{await post('/api/retrait',{id:r.id,withdrawalToken:r.token});keep({...r,withdrawn:true});openDialog('Participation retirée',`<p>Les réponses et le profil associés à ce code ont été supprimés de la collecte privée</p><p>Vos choix restent disponibles dans cet onglet pour continuer à jouer</p>`);}catch{openDialog('Retrait non confirmé',`<p>Les nouveaux envois sont arrêtés, mais la suppression n’a pas pu être confirmée</p><p>Conservez votre code et réessayez</p><code class="withdrawal-secret">${escapeHTML(r.id+'.'+r.token)}</code><div class="dialog-actions"><button data-collection="withdraw" data-id="${r.id}">Réessayer le retrait</button><button data-collection="download-code" data-id="${r.id}">Enregistrer le code</button></div>`);}refresh(state.remote||{});});}
 document.addEventListener('change',e=>{if(e.target.id==='collection-agree'){const b=document.querySelector('[data-collection="accept"]');if(b)b.disabled=!e.target.checked;}});
 document.addEventListener('click',e=>{const b=e.target.closest('[data-collection]');if(!b||b.disabled)return;switch(b.dataset.collection){case'accept':accept();break;case'decline':closeDialog();break;case'manage':manage();break;case'retry':send();break;case'download-code':downloadCode(b.dataset.id);break;case'withdraw':withdraw(b.dataset.id);break;}});
 return {offer,send,statusMarkup,manage};
})();
